# -*- coding: utf-8 -*-
"""Indonesia / IPA Kelas 9（Fase D。Buku Siswa IPA Kelas IX Kurikulum Merdeka）"""
from id_sci import H, nq, num, it


def f_listrik(R):
    k = R.choice(["V", "I", "R", "seri", "paralel", "P", "kWh"])
    if k == "V":
        I = R.choice([0.5, 1, 1.5, 2, 3])
        Rr = R.choice([4, 6, 10, 12, 20])
        return nq("Arus %s A mengalir pada hambatan %d Ω. Berapa tegangannya?" % (num(I), Rr), I * Rr, [I / Rr, Rr / I, I + Rr], "V", "V = I × R = %s × %d = %s V." % (num(I), Rr, num(I * Rr)))
    if k == "I":
        V = R.choice([6, 9, 12, 24, 220])
        Rr = R.choice([2, 3, 4, 6, 12])
        if V == 220:
            Rr = R.choice([44, 110, 440])
        return nq("Lampu dengan hambatan %d Ω dipasang pada tegangan %d V. Berapa kuat arusnya?" % (Rr, V), V / Rr, [V * Rr, Rr / V, V - Rr if V > Rr else V + Rr], "A",
                  "I = V ÷ R = %d ÷ %d = %s A." % (V, Rr, num(V / Rr)))
    if k == "R":
        I = R.choice([0.5, 2, 4])
        V = I * R.choice([3, 5, 6, 10])
        return nq("Tegangan %s V menghasilkan arus %s A pada sebuah penghambat. Berapa hambatannya?" % (num(V), num(I)), V / I, [V * I, I / V, V + I], "Ω", "R = V ÷ I = %s ÷ %s = %s Ω." % (num(V), num(I), num(V / I)))
    if k == "seri":
        a, b, c = R.sample([2, 3, 4, 5, 6, 8, 10], 3)
        return nq("Tiga hambatan %d Ω, %d Ω, dan %d Ω disusun seri. Berapa hambatan totalnya?" % (a, b, c), a + b + c, [1 / (1 / a + 1 / b + 1 / c), a * b * c, (a + b + c) / 3], "Ω",
                  "Rangkaian seri: Rtotal = %d + %d + %d = %d Ω." % (a, b, c, a + b + c))
    if k == "paralel":
        a, b = R.choice([(6, 3), (4, 4), (12, 6), (6, 6), (20, 5), (10, 10), (12, 4)])
        rt = a * b / (a + b)
        return nq("Dua hambatan %d Ω dan %d Ω disusun paralel. Berapa hambatan penggantinya?" % (a, b), rt, [a + b, (a + b) / 2 if (a + b) / 2 != rt else a * b, 1 / a + 1 / b], "Ω",
                  "1/Rp = 1/%d + 1/%d, jadi Rp = (%d × %d) ÷ (%d + %d) = %s Ω." % (a, b, a, b, a, b, num(rt)))
    if k == "P":
        V = R.choice([12, 220])
        I = R.choice([0.5, 1, 2, 5]) if V == 220 else R.choice([2, 3, 5])
        return nq("Sebuah alat bekerja pada tegangan %d V dengan arus %s A. Berapa dayanya?" % (V, num(I)), V * I, [V / I, I / V * 100, V + I], "W", "P = V × I = %d × %s = %s W." % (V, num(I), num(V * I)))
    P = R.choice([100, 200, 250, 400, 500])
    t = R.choice([2, 4, 5, 8, 10])
    tarif = R.choice([1000, 1500])

    def rp(x):
        return "Rp" + "{:,}".format(int(round(x))).replace(",", ".")
    kwh = P * t / 1000
    ans = kwh * tarif
    wr = []
    for w in (ans * 30, P * tarif / 1000, ans * 10, ans / 2):
        if rp(w) != rp(ans) and rp(w) not in wr:
            wr.append(rp(w))
    return it("Sebuah alat %d W dinyalakan %d jam sehari. Jika tarif listrik %s per kWh, berapa biaya listriknya sehari?" % (P, t, rp(tarif)), rp(ans), wr[:3],
              "Energi = %d W × %d jam = %s kWh; biaya = %s × %s = %s." % (P, t, num(kwh), num(kwh), rp(tarif), rp(ans)))


def f_genetika(R):
    pairs = [("bunga merah (M) dominan terhadap putih (m)", "M", "m", "merah", "putih"), ("biji bulat (B) dominan terhadap keriput (b)", "B", "b", "bulat", "keriput"),
             ("batang tinggi (T) dominan terhadap pendek (t)", "T", "t", "tinggi", "pendek"), ("rambut keriting (K) dominan terhadap lurus (k)", "K", "k", "keriting", "lurus")]
    sifat, A, a, dom, res = R.choice(pairs)
    k = R.choice(["F1", "F2fen", "F2gen", "test", "persen"])
    if k == "F1":
        return it("Pada persilangan dengan sifat %s, induk %s%s disilangkan dengan %s%s. Bagaimana fenotipe semua keturunan F1?" % (sifat, A, A, a, a), "100% " + dom,
                  ["100% " + res, "50%% %s dan 50%% %s" % (dom, res), "75%% %s dan 25%% %s" % (dom, res)], "Semua F1 bergenotipe %s%s, dan karena %s dominan, semuanya %s." % (A, a, A, dom))
    if k == "F2fen":
        return it("Dengan sifat %s, F1 %s%s disilangkan sesamanya. Berapa perbandingan fenotipe F2?" % (sifat, A, a), "%s : %s = 3 : 1" % (dom, res),
                  ["%s : %s = 1 : 1" % (dom, res), "%s : %s = 1 : 3" % (dom, res), "%s : %s = 1 : 2 : 1" % (dom, res)], "%s%s × %s%s menghasilkan %s%s, %s%s, %s%s, %s%s; tiga %s dan satu %s." % (A, a, A, a, A, A, A, a, A, a, a, a, dom, res))
    if k == "F2gen":
        return it("Dengan sifat %s, F1 %s%s disilangkan sesamanya. Berapa perbandingan genotipe F2?" % (sifat, A, a), "%s%s : %s%s : %s%s = 1 : 2 : 1" % (A, A, A, a, a, a),
                  ["%s%s : %s%s : %s%s = 3 : 1 : 0" % (A, A, A, a, a, a), "%s%s : %s%s : %s%s = 1 : 1 : 1" % (A, A, A, a, a, a), "%s%s : %s%s : %s%s = 2 : 1 : 1" % (A, A, A, a, a, a)],
                  "Kotak Punnett %s%s × %s%s menghasilkan 1 %s%s, 2 %s%s, dan 1 %s%s." % (A, a, A, a, A, A, A, a, a, a))
    if k == "test":
        return it("Dengan sifat %s, tanaman %s%s disilangkan dengan %s%s. Berapa perbandingan fenotipe keturunannya?" % (sifat, A, a, a, a), "%s : %s = 1 : 1" % (dom, res),
                  ["%s : %s = 3 : 1" % (dom, res), "semua %s" % dom, "semua %s" % res], "%s%s × %s%s menghasilkan %s%s dan %s%s dengan jumlah sama." % (A, a, a, a, A, a, a, a))
    n = R.choice([80, 120, 200, 400, 600])
    return nq("Dengan sifat %s, F1 %s%s disilangkan sesamanya dan menghasilkan %d keturunan. Berapa kira-kira yang bersifat %s?" % (sifat, A, a, n, res), n / 4, [n * 3 / 4, n / 2, n / 3], "",
              "Peluang %s adalah 1/4, jadi 1/4 × %d = %s." % (res, n, num(n / 4)))


def f_laju(R):
    k = R.choice(["luas", "suhu", "konsentrasi", "katalis"])
    rows = {"luas": ("serbuk pualam dan bongkahan pualam dimasukkan ke HCl yang sama", "serbuk pualam", "luas permukaan bidang sentuh yang lebih besar"),
            "suhu": ("tablet vitamin C dimasukkan ke air 20 °C dan air 50 °C", "di air 50 °C", "suhu yang lebih tinggi"),
            "konsentrasi": ("pita magnesium dimasukkan ke HCl 1 M dan HCl 2 M", "di HCl 2 M", "konsentrasi yang lebih besar"),
            "katalis": ("hidrogen peroksida diuraikan dengan dan tanpa batu kawi (MnO₂)", "dengan batu kawi", "adanya katalis")}
    q, a, why = rows[k]
    wr = {"luas": ["bongkahan pualam", "keduanya sama cepat", "tidak ada yang bereaksi"], "suhu": ["di air 20 °C", "keduanya sama cepat", "tidak ada yang bereaksi"],
          "konsentrasi": ["di HCl 1 M", "keduanya sama cepat", "tidak ada yang bereaksi"], "katalis": ["tanpa batu kawi", "keduanya sama cepat", "tidak ada yang bereaksi"]}[k]
    return it("Percobaan: %s. Mana yang bereaksi lebih cepat?" % q, a, wr, "Reaksi lebih cepat karena %s." % why)


